              <td colspan="6"></td>
            </tr>
          </tfoot>
        </table>
        @if (cancelError()) {
          <p role="alert" data-testid="invoice-cancel-error">{{ cancelError() }}</p>
        }
        @if (creditWarning()) {
          <p role="alert" data-testid="invoice-credit-warning">{{ creditWarning() }}</p>
        }
        @if (sendError()) {
          <p role="alert" data-testid="invoice-send-error">{{ sendError() }}</p>
        }
      }
    </section>
  `,
